import React, { useState } from "react";
import "./Bank.css";

function Bank() {
  const [balance, setBalance] = useState([]);
  const [updatebal, setUpdatebal] = useState([]);

  function addBalanceChange(event) {
    setUpdatebal(event.target.value);
  }

  const handleUpdateBalance = () => {
    let num = balance + updatebal;

    setBalance(num);
    console.log(balance);
  };

  return (
    <div>
      <div className="cont-bank">
        <label>Enter Amount(Rs.): </label>
        <input type="number" onChange={addBalanceChange} />
        <button onClick={handleUpdateBalance}>Add Balance</button>
      </div>
      <div>
        <label>Current Balance: </label>
        <label>{balance}</label>
      </div>
    </div>
  );
}

export default Bank;
